        // silently dropped by a plain get-then-clear.
        if (pendingTriggerReason.compareAndSet(reason, null)) {
            log.info("Draining debounced refresh trigger after cooldown: reason={}", reason)
            triggerAsyncRefresh(reason)
        }
    }
