import com.fasterxml.jackson.databind.ObjectMapper
import com.secman.config.VulnerabilityStatisticsCacheConfig
import com.secman.domain.VulnerabilityStatisticsCache
import com.secman.repository.VulnerabilityStatisticsCacheRepository
import com.secman.repository.VulnerabilityRepository
import com.secman.repository.projection.toSeverityDistributionDto
import jakarta.inject.Singleton
import jakarta.transaction.Transactional
import org.slf4j.LoggerFactory
import java.time.LocalDateTime

/**
 * Service for managing pre-computed vulnerability statistics cache
 *
 * Responsibilities:
 * - Refresh cache by running the 4 bounded SQL aggregates and serializing them to JSON
 * - Serve cached entries for "All Domains" admin views
 * - Respect feature flag (secman.statistics-cache.enabled)
 *
 * Cache keys:
 * - most_common → List<MostCommonVulnerabilityDto>
 * - most_vulnerable_products → List<MostVulnerableProductDto>
 * - severity_distribution → SeverityDistributionDto
 * - top_assets → List<TopAssetByVulnerabilitiesDto>
 */
@Singleton
open class VulnerabilityStatisticsCacheService(
    private val cacheRepository: VulnerabilityStatisticsCacheRepository,
    private val vulnerabilityRepository: VulnerabilityRepository,
    private val cacheConfig: VulnerabilityStatisticsCacheConfig,
    private val objectMapper: ObjectMapper
) {
    private val log = LoggerFactory.getLogger(VulnerabilityStatisticsCacheService::class.java)

    companion object {
        const val KEY_MOST_COMMON = "most_common"
        const val KEY_MOST_VULNERABLE_PRODUCTS = "most_vulnerable_products"
        const val KEY_SEVERITY_DISTRIBUTION = "severity_distribution"
        const val KEY_TOP_ASSETS = "top_assets"
    }

    fun isCacheEnabled(): Boolean = cacheConfig.enabled

    /**
     * Refresh all 4 statistics cache entries.
     *
     * Each entry comes from the SAME bounded SQL aggregate the live (cache-miss) path in
     * [VulnerabilityStatisticsService] uses, mapped through the same shared `toDto()`. Peak
     * heap is therefore constant — at most 10/10/~6/50 rows — regardless of table size.
     *
     * This replaced a fetch-the-whole-table-and-aggregate-in-Kotlin implementation. That
     * design existed to keep exception filtering off the SQL path, because the correlated
     * `NOT EXISTS` it would otherwise need could hold a pooled connection for minutes and
     * tripped HikariCP's leak detector (2026-07-15 incident). But it traded a
     * connection-hold problem for a heap problem: on 2026-07-30 the unfiltered
     * `vulnerability JOIN asset` fetch — retained twice, once raw and once filtered — ran a
     * 1 GB container out of heap mid-import.
     *
     * Both problems are solved by [com.secman.repository.VulnQuerySql.NOT_EXCEPTED], which
     * now reads the materialized `vulnerability.excepted` flag instead of re-deriving the
     * match per row. See that constant for why it is equivalent.
     *
     * Two consequences worth knowing:
     *  - This service is no longer the only consumer deriving exception state its own way, so
     *    the statistics finally agree with the vulnerability list they summarise.
     *  - The old in-memory severity comparisons were case-SENSITIVE (`== "CRITICAL"`) while
     *    severity is stored title-case ("Critical"), so `criticalCount`/`highCount` on
     *    most_vulnerable_products and top_assets were silently 0 for every imported row. The
     *    SQL aggregates compare under utf8mb4_general_ci and report the true counts, so those
     *    numbers jump on first refresh. That is the bug being fixed, not a regression.
     *
     * Each aggregate is refreshed independently: one failing query must not cost the other
     * three their refresh.
     *
     * Called at the end of MaterializedViewRefreshService.executeRefresh().
     */
    open fun refreshCache() {
        if (!cacheConfig.enabled) {
            log.info("Statistics cache is disabled, skipping refresh")
            return
        }

        log.info("Starting vulnerability statistics cache refresh")
        val overallStart = System.currentTimeMillis()

        refreshEntry(KEY_MOST_COMMON) {
            vulnerabilityRepository.findMostCommonVulnerabilitiesForAll().map { it.toDto() }
        }
        refreshEntry(KEY_MOST_VULNERABLE_PRODUCTS) {
            vulnerabilityRepository.findMostVulnerableProductsForAll().map { it.toDto() }
        }
        refreshEntry(KEY_SEVERITY_DISTRIBUTION) {
            vulnerabilityRepository.findSeverityDistributionForAll().toSeverityDistributionDto()
        }
        refreshEntry(KEY_TOP_ASSETS) {
            vulnerabilityRepository.findTopAssetsByVulnerabilitiesForAll().map { it.toDto() }
        }

        log.info("Statistics cache refresh completed in {}ms", System.currentTimeMillis() - overallStart)
    }

    /**
     * Run one aggregate, serialize it, and upsert it under [cacheKey], timing just that entry.
     * Failures are logged and swallowed so the remaining entries still refresh — a stale entry
     * is strictly better than three stale entries.
     *
     * The per-key duration is logged at INFO (four lines per refresh, not a hot path) because it
     * is the measurement needed to decide whether this cache should exist at all. Now that
     * VulnQuerySql.NOT_EXCEPTED is a sargable `excepted = 0` instead of a per-row correlated
     * subquery, these four queries may well be fast enough to serve live — which would let the
     * whole cache, and with it a class of cached-vs-live divergence, be deleted.
     *
     * Decision rule, to be applied against production numbers rather than guessed at: if every key
     * refreshes in comfortably under the p99 budget for an interactive request, retire the cache
     * and have VulnerabilityStatisticsService always query live. If any key is still seconds-slow,
     * keep the cache and record the measured number here. Do NOT add a covering index to speed
     * these up without measuring first — V217 deliberately removed indexes from `vulnerability`
     * because of write contention during concurrent CrowdStrike imports.
     */
    private fun refreshEntry(cacheKey: String, aggregate: () -> Any) {
        val start = System.currentTimeMillis()
        try {
            val json = objectMapper.writeValueAsString(aggregate())
            val durationMs = System.currentTimeMillis() - start
            upsertCache(cacheKey, json, durationMs)
            log.info("Refreshed statistics cache key '{}' in {}ms", cacheKey, durationMs)
        } catch (e: Exception) {
            log.error("Statistics cache refresh failed for key '{}': {}", cacheKey, e.message, e)
        }
    }

    /**
     * Get a cached entry by key, or null if cache is disabled or entry doesn't exist
     */
    fun getCachedEntry(cacheKey: String): VulnerabilityStatisticsCache? {
        if (!cacheConfig.enabled) return null
        return cacheRepository.findByCacheKey(cacheKey).orElse(null)
    }

    /**
     * Get the most recent lastRefreshedAt across all cache entries
     */
    fun getLastRefreshedAt(): LocalDateTime? {
        if (!cacheConfig.enabled) return null
        return listOf(KEY_MOST_COMMON, KEY_MOST_VULNERABLE_PRODUCTS, KEY_SEVERITY_DISTRIBUTION, KEY_TOP_ASSETS)
            .mapNotNull { cacheRepository.findByCacheKey(it).orElse(null)?.lastRefreshedAt }
            .maxOrNull()
    }

    @Transactional
    open fun upsertCache(cacheKey: String, json: String, durationMs: Long) {
        // Atomic native upsert (ON DUPLICATE KEY on the cache_key unique index). The previous
        // find-then-save/update was racy under concurrent refreshes: both saw "no row", both
        // inserted, and one refresh died on the unique constraint.
        cacheRepository.upsertByCacheKey(cacheKey, json, LocalDateTime.now(), durationMs)
    }
}
