            ids.isNotEmpty() -> {
                val updated = recomputeChunked(ids)
                log.info("excepted recompute after delete: scope={} assets={} rows={}", scope, ids.size, updated)
            }
            else -> log.debug("excepted recompute after delete: scope={} matched no assets", scope)
        }
    }

