     *
     * Features: 030-crowdstrike-asset-auto-creation, 032-servers-query-import
     *
     * @param request Save request (single or batch)
     * @param authentication Current authenticated user
     * @return Save response with statistics
     */
    @Post("/crowdstrike/vulnerabilities/save")
    open fun saveVulnerabilities(
        @Body @Valid request: CrowdStrikeSaveRequest,
        authentication: Authentication  // T012: Pass authentication to service
    ): HttpResponse<*> {
        val username = authentication.name
        log.info("Received CrowdStrike save request: hostname={}, count={}, user={}", request.hostname, request.vulnerabilities.size, username)

        return try {
            val response = crowdStrikeService.saveToDatabase(request, authentication)  // T012: Pass both parameters

            // Saving mutates the persisted rows that the DB-first lookup path serves, so the
            // 15-minute vulnerability_queries cache is now stale for this host. Without this, the
            // natural Refresh -> "Save to Database" -> Search flow would show pre-save data for up
            // to 15 minutes. Same non-fatal pattern the import service already uses; a cache
            // failure must never fail an otherwise successful save.
            if (response.vulnerabilitiesSaved > 0) {
                try {
                    queryService.invalidateAllCachedQueries()
                } catch (e: Exception) {
                    log.warn("Failed to invalidate vulnerability_queries cache after save", e)
                }
            }

            log.info("CrowdStrike save successful: {}, user={}", response.message, username)
            HttpResponse.ok(response)
        } catch (e: IllegalArgumentException) {
            log.warn("Invalid save request: user={}", username, e)
            HttpResponse.badRequest(mapOf("error" to (e.message ?: "Invalid request")))
        } catch (e: Exception) {
            log.error("Database error saving vulnerabilities: user={}", username, e)
            HttpResponse.status<Map<String, String>>(HttpStatus.INTERNAL_SERVER_ERROR)
                .body(mapOf("error" to "An internal error occurred while saving vulnerabilities"))
        }
    }

    /**
     * Batch import server vulnerabilities from CrowdStrike
     *
     * @param batches List of server vulnerability batches
     * @param authentication Current authenticated user
     * @return ImportStatisticsDto with detailed statistics
     *
     * Security: Inherits controller-level @Secured("ADMIN", "VULN") - only ADMIN/VULN roles can import
     *
     * Error responses:
     * - 400: Invalid request (validation failure)
    // per-transaction `@Transactional(isolation=...)` because Micronaut Data's
    // HibernateTransactionManager only honours custom isolation when connection
    // handling is DELAYED_ACQUISITION_AND_HOLD — setting it at the HikariCP layer
    // sidesteps that constraint cleanly. `DeadlockRetry` remains as a
    // backstop for residual races (PESSIMISTIC_WRITE contention on duplicate-asset
    // cleanup, lock-wait timeouts).
    @Transactional
    open fun importVulnerabilitiesForServer(batch: CrowdStrikeVulnerabilityBatchDto): ServerImportResult {
        log.debug("Importing vulnerabilities for server: {}", batch.hostname)

        val (candidates, normalizedAids) = resolveAssetCandidates(batch)

        val (asset, isNewAsset) = if (candidates.isNotEmpty()) {
            val bestMatch = selectBestCandidate(candidates, batch.hostname)

            // Clean up: We will delete vulnerabilities for ALL candidates to avoid inflation
            // The "best match" will get new vulnerabilities populated below

            Pair(updateAsset(bestMatch, batch), false)
        } else {
            Pair(createNewAsset(batch), true)
        }
        synchronizeCrowdStrikeIdentities(asset, batch.hostname, normalizedAids)

        // Delete existing vulnerabilities for this asset AND any duplicates
        // This ensures that "stale" duplicate assets don't contribute to inflated counts
        val assetIdsToClean = if (candidates.isNotEmpty()) {
            candidates.mapNotNull { it.id }
        } else {
            listOf(asset.id!!)
        }

        // Snapshot (CVE, product) -> earliest firstSeenAt across the surviving asset
        // and any duplicates we are about to clean up. Used below to preserve the
        // original detection date across re-imports (V208).
        val existingFirstSeen = mutableMapOf<Pair<String?, String?>, LocalDateTime>()
        for (id in assetIdsToClean) {
            vulnerabilityRepository.findByAssetId(id, io.micronaut.data.model.Pageable.UNPAGED)
                .content
                .forEach { existing ->
                    val key = existing.vulnerabilityId to existing.vulnerableProductVersions
                    val anchor = existing.firstSeenAt ?: existing.scanTimestamp
                    val current = existingFirstSeen[key]
                    if (current == null || anchor.isBefore(current)) {
                        existingFirstSeen[key] = anchor
                    }
                }
        }

        // Filter vulnerabilities: require CVE ID and optionally require patch publication date.
        // Applied BEFORE the delete below: when every incoming row is filtered out, the old
        // delete-first order committed the delete and inserted nothing — the host silently
        // ended at 0 rows while looking freshly imported.
        val requirePatchDate = vulnerabilitySettings.requirePatchPublicationDate
        var vulnsWithCve = batch.vulnerabilities.filter { vuln ->
            !vuln.cveId.isNullOrBlank() && (!requirePatchDate || vuln.patchPublicationDate != null)
        }
        val skippedCount = batch.vulnerabilities.size - vulnsWithCve.size

        if (skippedCount > 0) {
            log.debug("Skipped {} vulnerabilities (no CVE ID{}) for asset '{}'",
                skippedCount, if (requirePatchDate) " or no patch publication date" else "", asset.name)
        }

        // Scope of the transactional replace: only CrowdStrike-sourced rows, and only the
        // severities this run actually queried (when the CLI stated them). The former
        // unscoped deleteByAssetId destroyed MEDIUM/LOW rows and XLSX/nmap/manual rows on
        // every import with nothing to reinsert them. The idempotent contract (missing CVE
        // = remediated) holds unchanged for the in-scope slice; rows a CVE leaves behind at
        // an out-of-scope severity are cleaned up by the reconcile sweep's severity-history
        // union, not here.
        val runSeveritiesUpper = batch.runSeverities
            ?.map { it.trim().uppercase() }
            ?.filter { it.isNotBlank() }
            ?.distinct()
            ?.takeIf { it.isNotEmpty() }

        var deletedCount = 0
        if (batch.vulnerabilities.isNotEmpty() && vulnsWithCve.isEmpty()) {
            // Everything the batch carried was filtered out (blank CVE ids, or the
            // require-patch-date setting). Deleting now would be delete-without-reinsert:
            // keep the existing rows and say so loudly. lastSeen/crowdStrikeLastImportedAt
            // were already refreshed above — the host WAS seen.
            log.warn(
                "Import: ALL {} incoming vulnerabilities for asset '{}' were filtered out " +
                "(requirePatchPublicationDate={}) — keeping existing rows, skipping delete",
                batch.vulnerabilities.size, asset.name, requirePatchDate
            )
        } else {
            for (id in assetIdsToClean) {
                // Lock asset to prevent concurrent import races
                entityManager.find(Asset::class.java, id, LockModeType.PESSIMISTIC_WRITE)
                val count = if (runSeveritiesUpper != null) {
                    vulnerabilityRepository.deleteByAssetIdScopedToSourceAndSeverities(
                        assetId = id,
                        source = VulnerabilitySources.CROWDSTRIKE,
                        severitiesUpper = runSeveritiesUpper
                    )
                } else {
                    vulnerabilityRepository.deleteByAssetIdAndSource(id, VulnerabilitySources.CROWDSTRIKE)
                }
                deletedCount += count
            }

            if (deletedCount > 0) {
                // INFO, not DEBUG: prod runs at INFO, and per-host replace volumes are the
                // first thing an over-deletion investigation needs (A09: actor is the import
                // pipeline, target is the asset, outcome is the replaced-row count).
                log.info(
                    "Import: replaced {} CrowdStrike row(s) on asset '{}' (severities={}, {} duplicate sibling(s), incoming={})",
                    deletedCount, asset.name, runSeveritiesUpper ?: "ALL",
                    assetIdsToClean.size - 1, vulnsWithCve.size
